search=[]
def page(filename,title,content,*,article=False,extra=''):
 top=''.join(f'<a href="{href}"'+(' aria-current="page"'if href==filename else'')+f'>{label}</a>'for href,label in nav)
 sidebar=''.join('<div class="label">'+group+'</div>'+''.join(f'<a href="{href}" class="'+('current'if href==filename else'')+'">'+label+'</a>'for href,label in links)for group,links in side)
 doc=f'''<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="P2导航V2完整项目手册，统一Python/TypeScript SDK，WATER兼容范围、接口与开发文档。"><title>{title} · NavBridge</title><link rel="icon" href="assets/favicon.svg" type="image/svg+xml"><link rel="stylesheet" href="assets/site.css"><script src="assets/site.js" defer></script>{extra}</head><body><a class="skip" href="#content">跳到正文</a><header class="top"><a class="brand" href="index.html">{logo}NavBridge<small>P2 NAVIGATION</small></a><nav class="nav" aria-label="主导航">{top}</nav><div class="searchbox"><input id="search" type="search" placeholder="搜索文档 /" aria-label="搜索文档" autocomplete="off"><div id="search-results" hidden></div></div><button class="menu" aria-label="展开导航" aria-expanded="false">菜单</button></header><div class="shell"><aside class="side" aria-label="文档目录">{sidebar}<div class="release">NAVIGATION <b>V2</b><br>SDK <b>0.1.0</b><br>更新于 2026.11.05<br><br>静态文档与合成预览<br>不连接真实机器人</div></aside><main id="content" class="{'article'if article else''}">{content}</main></div><footer class="footer"><span>NavBridge · P2 Navigation Project · MIT 自有代码</span><span>导航基线与 SDK 独立版本 · <a href="compatibility.html">兼容范围</a> · <a href="https://github.com/lizi-learn/mid360s-lidar-navigation">GitHub</a></span></footer></body></html>'''
 (out/filename).write_text(doc)
 search.append({'title':title,'section':'页面','url':filename,'text':re.sub('<[^>]+>',' ',content)[:2500]})
def md_page(filename,title,source):
 text=(R/source).read_text();body=markdown.markdown(text,extensions=['tables','fenced_code','toc'])
 body=re.sub(r'href="(?!https?://|#)([^"#]+\.md)(#[^"]*)?"',lambda m:'href="'+{'PROJECT_GUIDE.md':'guide.html','COMPATIBILITY.md':'compatibility.html','README.md':'start.html'}.get(m[1],'https://github.com/lizi-learn/mid360s-lidar-navigation/blob/main/'+str(Path(source).parent/m[1]))+(m[2]or'')+'"',body)
 body=body.replace('href="../../api/navigation.openapi.json"','href="downloads/navigation.openapi.json"')
 headings=re.findall(r'<h2 id="([^"]+)">(.+?)</h2>',body)
 toc='<div class="doc-toc">'+''.join('<a href="#'+anchor+'">'+label+'</a>'for anchor,label in headings)+'</div>'
 first=body.find('</h1>')+5;body=body[:first]+toc+body[first:]
 for anchor,label in headings:search.append({'title':re.sub('<[^>]+>','',label),'section':title,'url':filename+'#'+anchor,'text':label})
 page(filename,title,body,article=True)

