for path,methods in api['paths'].items():
 for method,data in methods.items():
  cards.append(f'<section class="api-method" data-method="{method}" id="{data["operationId"]}"><span class="verb">{method.upper()}</span><code>{html.escape(path)}</code><p>{html.escape(data["summary"])}</p>'+('<p class="fine">Body: '+html.escape(data['requestBody']['content']['application/json']['schema']['$ref'].split('/')[-1])+'</p>'if 'requestBody'in data else'')+'</section>')
  search.append({'title':method.upper()+' '+path,'section':'API','url':'api.html#'+data['operationId'],'text':data['summary']})
page('api.html','HTTP API 参考','''<div class="eyebrow">API REFERENCE / 1.0</div><h1>任务、点位与状态。</h1><p>基础地址 <code>http://127.0.0.1:18940</code>。JSON 使用米 / 弧度；未知硬件数据保留 null。接口由独立网关提供。</p><div class="actions"><a class="button primary" href="downloads/navigation.openapi.json" download>下载 OpenAPI 3.1</a><a class="button" href="guide.html">任务语义与错误</a></div><div class="scope">POST 返回 accepted 只表示已受理。到达、介绍结束、人工接管与未知结果分别记录；客户端等待超时不取消导航。</div><div class="filterbar" aria-label="筛选API方法"><button class="selected" data-api-filter="all">全部</button><button data-api-filter="get">GET 查询</button><button data-api-filter="post">POST 任务</button><button data-api-filter="delete">DELETE</button></div>'''+''.join(cards)+'''<h2>结构化错误</h2><pre><code>{"error":{"code":"UNSUPPORTED_CAPABILITY",
  "message":"该 provider 尚未实现此能力","details":{}}}</code></pre><p>Idempotency-Key 相同且请求内容一致时返回原任务；相同键换内容返回409。未知派发结果不会自动重试。详细字段与状态模型见 OpenAPI 文件。</p>''')
page('demo.html','导览交互演示','''<div class="eyebrow">SYNTHETIC WORKFLOW PREVIEW</div><h1>一条路线，完整走完接待流程。</h1><p>点击地图点位查看话术，开始后依次演示行进、到点介绍、停留和等待下一站。</p><div class="scope"><strong>合成交互预览。</strong> 下图为虚构场地与编写好的示例路线，不是办公室地图、Nav2仿真或物理运动验证；不连接实机，不播放声音。</div><div class="demo-layout"><div class="mapwrap"><svg id="demo-map" viewBox="0 0 650 340" role="img" aria-label="合成接待地图"><rect x="25" y="30" width="600" height="280" rx="4" fill="#fafbf6" stroke="#8ea397" stroke-width="5"/><path d="M330 30v150h120M330 180v40" fill="none" stroke="#8ea397" stroke-width="9"/><rect x="47" y="57" width="88" height="80" rx="5" fill="#dfe9df"/><text x="91" y="102" text-anchor="middle" font-size="12" fill="#62776b">接待区</text><rect x="455" y="39" width="140" height="35" rx="4" fill="#e8d9c7"/><text x="525" y="61" text-anchor="middle" font-size="11" fill="#806a52">展示柜</text><path d="M95 250H190V95H275M275 95V250H480V115M480 115V250H95" stroke="#c9d6cb" stroke-width="2" fill="none" stroke-dasharray="6 5"/><polyline id="demo-route" stroke="#08766c" stroke-width="3" fill="none"/><g id="obstacle" hidden><rect x="170" y="160" width="40" height="40" rx="7" fill="#d69b6b"/><text x="190" y="185" text-anchor="middle" font-size="11" fill="#fff">阻挡</text></g><g id="demo-robot"><circle r="17" fill="#d9a269" stroke="#fff" stroke-width="3"/><path d="M0 -11L7 7L0 3L-7 7Z" fill="#fff"/></g><text x="37" y="328" font-size="10" fill="#73847b">SYNTHETIC · 非真实地图 · 非物理仿真</text></svg></div><div class="demopanel"><div><h3 id="demo-station">接待起点</h3><span class="badge">站点 <span id="demo-step">1 / 4</span></span><div class="demo-status" id="demo-status" role="status" aria-live="polite"></div><p id="demo-speech"></p></div><div><div class="demo-controls"><button id="demo-start" class="primary">开始预览</button><button id="demo-pause">暂停</button><button id="demo-next" disabled>下一站</button><button id="demo-reset">重置</button><button id="demo-obstacle" aria-pressed="false">临时阻挡</button></div><div class="demo-log" id="demo-log" aria-label="合成任务事件"></div></div></div></div><p class="fine">正式管理工作台支持在同一地图填写点位名称、方向、产品话术、停留与路线。此页只展示操作方式，真实功能请在私有 Console 的 /reception 使用。</p>''',extra='<script src="assets/demo.js" defer></script>')
dl=out/'downloads';dl.mkdir(exist_ok=True)
# Source download is exactly the committed public tree, never arbitrary untracked files.
archive=R/'dist/p2-navigation-sdk-0.1.0-source.zip';archive.parent.mkdir(exist_ok=True)
with archive.open('wb') as output:
 subprocess.run(['git','archive','--format=zip','--prefix=p2-navigation-sdk-0.1.0/','HEAD'],cwd=R,stdout=output,check=True)
artifacts=[(R/'dist/p2_navigation_sdk-0.1.0-py3-none-any.whl','Python SDK','Python 3.10+ · 无第三方运行依赖'),(R/'dist/p2-navigation-sdk-0.1.0.tgz','TypeScript SDK','Node 18+ · 含类型声明'),(R/'output/pdf/P2-Navigation-V2-SDK-Manual.pdf','完整导航手册 PDF','架构 / 运维 / 功能 / SDK / 兼容矩阵'),(R/'api/navigation.openapi.json','OpenAPI 3.1','HTTP接口的机器可读合同'),(archive,'公开完整源码 ZIP','自有公开源码及上游许可说明；不含私有资产')]
items=[];manifest=[]
for path,title,description in artifacts:
 if not path.exists():raise SystemExit('Missing real download: '+str(path))
 shutil.copy2(path,dl/path.name);digest=hashlib.sha256(path.read_bytes()).hexdigest();manifest.append({'file':path.name,'sha256':digest,'bytes':path.stat().st_size})
 items.append('<div class="download"><b>'+title+'</b><small>'+description+'</small><a href="downloads/'+path.name+'" download>'+path.name+' ↓</a><div class="hash">SHA256 '+digest+'</div></div>')
(dl/'SHA256SUMS.txt').write_text('\n'.join(x['sha256']+'  '+x['file']for x in manifest)+'\n');(dl/'manifest.json').write_text(json.dumps({'version':'0.1.0','navigation_baseline':'baseline-v2','files':manifest},ensure_ascii=False,indent=2)+'\n')
page('downloads.html','SDK 与手册下载','''<div class="eyebrow">RELEASE ASSETS / 0.1.0</div><h1>文档、客户端和合同，一起交付。</h1><p>SDK 首版与导航 V2 基线独立版本。所有下载均为实际构建文件，下面列出逐个 SHA256。</p><div class="scope">首版已做本地合同验证；同事实际 SDK / 云迹固件尚未互通验证。包内不含私有地图、厂家驱动/策略或凭据。</div><div class="download-grid">'''+''.join(items)+'''</div><div class="actions"><a class="button" href="downloads/SHA256SUMS.txt" download>下载校验清单</a><a class="button" href="https://github.com/lizi-learn/mid360s-lidar-navigation/releases">GitHub Releases</a></div><h2>本地安装</h2><pre><code>python -m pip install ./p2_navigation_sdk-0.1.0-py3-none-any.whl
npm install ./p2-navigation-sdk-0.1.0.tgz
navbridge --backend mock --water-bridge-port 31001</code></pre><p>从mock开始验证业务调用；完整依赖、P2/WATER连接与迁移边界见快速接入和完整手册。</p>''')
(out/'search-index.json').write_text(json.dumps(search,ensure_ascii=False));(out/'assets/favicon.svg').write_text('<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 36 36">'+logo.split('>',1)[1].rsplit('</svg>',1)[0]+'</svg>')
(out/'_headers').write_text("/*\n  X-Content-Type-Options: nosniff\n  Referrer-Policy: strict-origin-when-cross-origin\n  Permissions-Policy: camera=(), microphone=(), geolocation=()\n  Content-Security-Policy: default-src 'self'; script-src 'self'; style-src 'self'; img-src 'self' data:; connect-src 'self'; object-src 'none'; base-uri 'self'; frame-ancestors 'none'\n/assets/*\n  Cache-Control: public, max-age=3600\n")
print(json.dumps({'site':str(out),'pages':7,'downloads':manifest},ensure_ascii=False))
